// ============================================================================
// File: tb/v3/tb_ch01_fifo_out.v
// Module: tb_ch01_fifo_out
// Description:
//   Cycle-accurate testbench for rtl/v3/ch01_fifo_out.v (Return Path F0 FIFO):
//   - Reads cycle-by-cycle stimulus from tb_ch01_fifo_out_stim.txt.
//   - Reads expected trace from tb_ch01_fifo_out_expected.txt generated by Python twin.
//   - Compares bit-for-bit and cycle-for-cycle:
//     * st_ready
//     * mm_waitrequest
//     * mm_readdata (16-bit payload)
//     * dut.words_used (FIFO occupancy count)
//   - Covers >= 200 vectors including single push/pop, capacity saturation (512 words),
//     full backpressure (st_ready = 0), empty waitrequest, and random read/write interleaving.
//   - Fully compatible with `iverilog -g2012 -Wall`.
// ============================================================================

`timescale 1ns/1ps

module tb_ch01_fifo_out;

    reg clk = 0;
    always #10 clk = ~clk; // 50 MHz clock (20 ns period)

    reg         rst_n;
    reg  [15:0] st_data;
    reg         st_valid;
    wire        st_ready;

    reg         mm_read;
    wire [31:0] mm_readdata;
    wire        mm_waitrequest;

    reg         csr_read;
    reg  [2:0]  csr_address;
    wire [31:0] csr_readdata;

    // Instantiate DUT
    ch01_fifo_out #(
        .ADDR_WIDTH(9) // 2^9 = 512 words
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .st_data(st_data),
        .st_valid(st_valid),
        .st_ready(st_ready),
        .mm_read(mm_read),
        .mm_readdata(mm_readdata),
        .mm_waitrequest(mm_waitrequest),
        .csr_read(csr_read),
        .csr_address(csr_address),
        .csr_readdata(csr_readdata)
    );

    integer stim_fd;
    integer exp_fd;
    integer cycle_idx;
    integer errors;

    // Stimulus variables
    integer stim_vld;
    reg [15:0] stim_sdata;
    integer stim_rd;

    // Expected variables
    integer exp_c;
    integer exp_vld;
    reg [15:0] exp_sdata;
    integer exp_rd;
    integer exp_rdy;
    integer exp_wreq;
    reg [15:0] exp_rdata;
    integer exp_used;

    initial begin
        rst_n = 0;
        st_data = 16'd0;
        st_valid = 0;
        mm_read = 0;
        csr_read = 0;
        csr_address = 3'd0;
        cycle_idx = 0;
        errors = 0;

        // Open stimulus file
        stim_fd = $fopen("verify_v3/tb_ch01_fifo_out_stim.txt", "r");
        if (stim_fd == 0) stim_fd = $fopen("tb_ch01_fifo_out_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("ERROR: Cannot open tb_ch01_fifo_out_stim.txt");
            $finish;
        end

        // Open expected trace file
        exp_fd = $fopen("verify_v3/tb_ch01_fifo_out_expected.txt", "r");
        if (exp_fd == 0) exp_fd = $fopen("tb_ch01_fifo_out_expected.txt", "r");
        if (exp_fd == 0) begin
            $display("ERROR: Cannot open tb_ch01_fifo_out_expected.txt");
            $finish;
        end

        // Reset pulse
        repeat (3) @(negedge clk);
        rst_n = 1;
        @(negedge clk);

        $display("=== STARTING CH01 RETURN FIFO OUT CYCLE-BY-CYCLE VERIFICATION ===");

        // Run cycle-by-cycle
        while ($fscanf(stim_fd, "%d %h %d\n", stim_vld, stim_sdata, stim_rd) == 3 &&
               $fscanf(exp_fd, "%d %d %h %d %d %d %h %d\n",
                       exp_c, exp_vld, exp_sdata, exp_rd, exp_rdy, exp_wreq, exp_rdata, exp_used) == 8) begin

            // Drive inputs before posedge clk
            st_valid <= (stim_vld != 0) ? 1'b1 : 1'b0;
            st_data  <= stim_sdata;
            mm_read  <= (stim_rd != 0) ? 1'b1 : 1'b0;

            // Wait for posedge clk (RTL updates) and then check at negedge clk (stable)
            @(posedge clk);
            #1; // Short delta after posedge

            // Check outputs against expected
            if (st_ready !== ((exp_rdy != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: st_ready mismatch (got %b, exp %0d)",
                         cycle_idx, st_ready, exp_rdy);
                errors = errors + 1;
            end

            if (mm_waitrequest !== ((exp_wreq != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: mm_waitrequest mismatch (got %b, exp %0d)",
                         cycle_idx, mm_waitrequest, exp_wreq);
                errors = errors + 1;
            end

            if (mm_readdata[15:0] !== exp_rdata) begin
                $display("[FAIL] Cycle %0d: mm_readdata mismatch (got 0x%04x, exp 0x%04x)",
                         cycle_idx, mm_readdata[15:0], exp_rdata);
                errors = errors + 1;
            end

            if (dut.words_used !== exp_used[9:0]) begin
                $display("[FAIL] Cycle %0d: words_used mismatch (got %0d, exp %0d)",
                         cycle_idx, dut.words_used, exp_used);
                errors = errors + 1;
            end

            if (errors >= 20) begin
                $display("Too many errors. Aborting simulation.");
                $finish;
            end

            cycle_idx = cycle_idx + 1;
        end

        $fclose(stim_fd);
        $fclose(exp_fd);

        $display("Simulation completed %0d cycles.", cycle_idx);
        $display("Total comparison errors: %0d", errors);

        if (errors == 0 && cycle_idx >= 200) begin
            $display("=== [PASS] CH01 RETURN FIFO OUT MATCHED PYTHON TWIN BIT-FOR-BIT AND CYCLE-FOR-CYCLE ON %0d CYCLES ===", cycle_idx);
        end else begin
            $display("=== [FAIL] CH01 RETURN FIFO OUT FAILED WITH %0d ERRORS ===", errors);
        end

        $finish;
    end

endmodule
